function el(id){return document.getElementById(id)}
function escapeHtml(t){return String(t).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
var count={};REC.forEach(function(r){(r.ak||[]).concat(r.medium?[r.medium]:[]).forEach(function(x){count[x]=(count[x]||0)+1})});
function render(){var q=el('ult-search').value.trim().toLowerCase(),cat=el('ult-filter').value;
var list=REC.filter(function(r){return (!cat||r.category===cat)&&(!q||atlasMatches([r.title,r.category,r.tip,r.lighting,r.extra,r.medium||'',r.ak.map(function(a){return a+' '+NAMES[a]}).join(' '),r.citadel.join(' ')].join(' '),q))});
el('ult-count').textContent=list.length+' recettes affichées / '+REC.length;
el('ult-cards').innerHTML=list.map(function(r){return '<details class="ult-card"><summary><span class="ult-tag">'+escapeHtml(r.category)+'</span><div>'+escapeHtml(r.title)+'</div></summary><div class="ult-body"><p>'+escapeHtml(r.lighting)+'</p><ol>'+r.ak.map(function(a,i){return '<li><b>'+escapeHtml(r.stages[i])+'</b> — '+escapeHtml(a+' '+NAMES[a])+'</li>'}).join('')+'</ol>'+(r.medium?'<p><b>Auxiliaire :</b> '+escapeHtml(r.medium+' '+NAMES[r.medium])+'</p>':'')+'<p><b>Placement :</b> '+escapeHtml(r.tip)+'</p><p class="ult-cit"><b>Citadel (palette de substitution artistique) :</b> '+escapeHtml(r.citadel.join(' · '))+'</p><p class="ult-cit"><b>Shade / Contrast / Technical :</b> '+escapeHtml(r.extra)+'</p></div></details>'}).join('')||'<p>Aucune recette trouvée. Efface les filtres pour tout retrouver.</p>'}
function renderPots(){var q=el('ult-paint-search').value.toLowerCase();var list=Object.keys(NAMES).filter(function(k){return (k+' '+NAMES[k]).toLowerCase().includes(q)});el('ult-paints').innerHTML=list.map(function(k){return '<div class="ult-pot"><b>'+k+'</b> · '+escapeHtml(NAMES[k])+'<br><button type="button" data-ult-pot="'+k+'">'+(count[k]||0)+' recette(s) → voir</button></div>'}).join('')}
function init(){if(!el('ult-cards'))return;var cats=Array.from(new Set(REC.map(function(r){return r.category})));cats.forEach(function(c){var o=document.createElement('option');o.value=c;o.textContent=c;el('ult-filter').appendChild(o)});el('ult-coverage').textContent=Object.keys(count).length+' / 233 références mobilisées';el('ult-search').addEventListener('input',render);el('ult-filter').addEventListener('change',render);el('ult-paint-search').addEventListener('input',renderPots);el('ult-reset').addEventListener('click',function(){el('ult-search').value='';el('ult-filter').value='';render()});el('ult-paints').addEventListener('click',function(e){var b=e.target.closest('[data-ult-pot]');if(!b)return;el('ult-search').value=b.getAttribute('data-ult-pot');el('ult-filter').value='';render();el('ult-cards').scrollIntoView({behavior:'auto'})});render();renderPots();
var mobile=el('atlas-mobile-select');if(mobile){mobile.addEventListener('change',function(){if(mobile.value==='ultime'){document.body.setAttribute('data-mobile-tab','ultime');document.querySelectorAll('.atlas-view').forEach(function(x){x.hidden=x.getAttribute('data-atlas-tab')!=='ultime'});}})}
var nav=document.getElementById('atlas-main-tabs');if(nav){nav.addEventListener('click',function(e){var b=e.target.closest('[data-main-tab]');if(!b)return;if(b.getAttribute('data-main-tab')==='ultime'){document.querySelectorAll('.atlas-view').forEach(function(x){x.hidden=x.getAttribute('data-atlas-tab')!=='ultime'});if(mobile)mobile.value='ultime';document.body.setAttribute('data-mobile-tab','ultime');}})}
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
